def solve():
    face = Q(10000000)
    base_rate = Q("3.1")
    baseline = Q(480000)
    divest_share = Q(4)
    if divest_share >= 5:
        applicable = baseline * (1 - divest_share / 100)
    else:
        applicable = baseline
    target = applicable * (1 - Q(10) / 100)
    verified = Q("89.75") / 100 * baseline
    excess = verified - target
    if excess > Q(5) / 100 * target:
        step = Q("0.20")
    elif excess > 0:
        step = Q("0.10")
    else:
        step = Q(0)
    stepped_rate = base_rate + step
    # coupons paid 2026..2031; those on/after 30 June 2028: 2028..2031
    years = list(range(2026, 2032))
    total = Q(0)
    count = 0
    for y in years:
        if y >= 2028:
            total += face * stepped_rate / 100
            count += 1
        else:
            total += face * base_rate / 100
    return {
        "final": total,
        "applicable_baseline": applicable,
        "emissions_threshold": target,
        "stepped_coupon_rate": stepped_rate,
        "stepped_coupon_count": count,
    }
